queries:
SELECT AVG(UA)
FROM Laboratory
WHERE ID IN (SELECT ID FROM Laboratory WHERE `U-PRO` = '-')
  AND ID IN (SELECT ID FROM Laboratory WHERE RA = '-');
SELECT ID, AVG(GOT), AVG(GPT)
FROM Laboratory
WHERE ID IN (SELECT ID FROM Laboratory WHERE `U-PRO` = '-' AND RA = '-')
GROUP BY ID;
SELECT ID, AVG(TAT - TAT2) FROM Laboratory WHERE TAT IS NOT NULL AND TAT2 IS NOT NULL GROUP BY ID;
SELECT ID, AVG(TAT) - AVG(TAT2) FROM Laboratory GROUP BY ID
SELECT AVG(avg_pt) FROM (SELECT ID, AVG(PT) AS avg_pt FROM Laboratory WHERE PT IS NOT NULL GROUP BY ID);
